def order_totals(conn):
    report = []
    for c in conn.execute('SELECT id, name FROM customers ORDER BY id').fetchall():
        rows = conn.execute('SELECT * FROM orders WHERE customer_id = ?', (c['id'],)).fetchall()
        report.append({'name': c['name'], 'orders': len(rows), 'total': sum(r['total'] for r in rows)})
    return report

