import { PrismaClient } from '@prisma/client'
const prisma = new PrismaClient()

export async function dashboard() {
  const users = await prisma.user.findMany()
  return Promise.all(
    users.map(async (u) => ({
      name: u.name,
      posts: await prisma.post.findMany({ where: { authorId: u.id } }),
    })),
  )
}

